" stroke-width=\"2\"><path d=\"M12 3l7 4v5c0 5-3.5 8-7 9-3.5-1-7-4-7-9V7l7-4z\"/><path d=\"M9 12l2 2 4-5\"/></svg>\n          </div>\n          <h3 class=\"pq-card-title\">Mises &agrave; jour</h3>\n          <p class=\"pq-card-text\">Suivi des &eacute;volutions et alertes lorsque les pratiques changent.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"pq-section pq-section-muted\">\n    <div class=\"pq-layout-container\">\n      <div class=\"pq-section-header\">\n        <p class=\"pq-section-kicker\">Workflow recommand&eacute;</p>\n        <h2 class=\"pq-section-title\">Parcours op&eacute;rationnel</h2>\n        <p class=\"pq-section-text\">Ces &eacute;tapes donnent au visiteur une logique claire et limitent les demandes incompl&egrave;tes.</p>\n      </div>\n      <ol class=\"pq-steps\">\n        \n        <li class=\"pq-step\">\n          <div class=\"pq-step-number\">1</div>\n          <h3 class=\"pq-step-title\">Identifier le site</h3>\n          <p class=\"pq-step-text\">Type de b&acirc;timent, usage et niveau de risque.</p>\n        </li>\n        <li class=\"pq-step\">\n          <div class=\"pq-step-number\">2</div>\n          <h3 class=\"pq-step-title\">Relier la norme</h3>\n          <p class=\"pq-step-text\">D&eacute;terminer les textes et exigences applicables.</p>\n        </li>\n        <li class=\"pq-step\">\n          <div class=\"pq-step-number\">3</div>\n          <h3 class=\"pq-step-title\">V&eacute;rifier</h3>\n          <p class=\"pq-step-text\">Contr&ocirc;ler les points mesurables et la documentation.</p>\n        </li>\n        <li class=\"pq-step\">\n          <div class=\"pq-step-number\">4</div>\n          <h3 class=\"pq-step-title\">Documenter</h3>\n          <p class=\"pq-step-text\">Archiver les preuves et r&eacute;serves.</p>\n        </li>\n      </ol>\n    </div>\n  </section>\n\n  <section class=\"pq-section\">\n    <div class=\"pq-layout-container pq-grid-2\">\n      <div class=\"pq-panel\">\n        <h2 class=\"pq-panel-title\">Points &agrave; pr&eacute;parer</h2>\n        <ul class=\"pq-checklist\">\n          \n        <li class=\"pq-check-item\">\n          <span class=\"pq-check-icon\">&check;</span>\n          <span>Ne pas publier de texte normatif sans droits.</span>\n        </li>\n        <li class=\"pq-check-item\">\n          <span class=\"pq-check-icon\">&check;</span>\n          <span>Pr&eacute;ciser la date et le statut de chaque ressource.</span>\n        </li>\n        <li class=\"pq-check-item\">\n          <span class=\"pq-check-icon\">&check;</span>\n          <span>Relier norme, point de contr&ocirc;le et preuve attendue.</span>\n        </li>\n        <li class=\"pq-check-item\">\n          <span class=\"pq-check-icon\">&check;</span>\n          <span>Inclure une voie de contact pour les cas sp&eacute;cifiques.</span>\n        </li>\n        </ul>\n      </div>\n      <div class=\"pq-result\">\n        <p class=\"pq-result-kicker\">R&eacute;sultat attendu</p>\n        <h2 class=\"pq-result-title\">Une page plus robuste et plus utile</h2>\n        <p class=\"pq-result-text\">La page rend la norme compr&eacute;hensible sans la simplifier abusivement.</p>\n        <p class=\"pq-result-note\">Ce mod&egrave;le est pens&eacute; pour &ecirc;tre coll&eacute; dans le builder, rester lisible sur mobile et conserver une hi&eacute;rarchie claire apr&egrave;s publication.</p>\n      </div>\n    </div>\n  </section>\n</div>\n"
